  ::view-transition-new(.slide-down) {
    animation: none;
  }

  ::view-transition-old(.slide-up) {
    animation: none;
  }

  ::view-transition-new(.slide-up) {
    animation:
      var(--duration-enter) ease-out var(--duration-exit) both fade,
      var(--duration-enter) ease-out var(--duration-exit) both slide-y;
  }

  @keyframes fade {
    from {
      filter: blur(3px);
      opacity: 0;
    }
    to {
      filter: blur(0);
      opacity: 1;
    }
  }

  @keyframes slide-y {
    from {
      transform: translateY(10px);
    }
    to {
      transform: translateY(0);
    }
  }

  @keyframes slide-y-reverse {
    from {
      transform: translateY(0);
    }
    to {
      transform: translateY(10px);
    }
  }

  ::view-transition-old(.nav-forward) {
    animation:
      150ms ease-in both fade reverse,
      400ms ease-in-out both slide-left-reverse;
  }

  ::view-transition-new(.nav-forward) {
    animation:
      210ms ease-out 150ms both fade,
      400ms ease-in-out both slide-left;
  }

  ::view-transition-old(.nav-back) {
    animation:
      150ms ease-in both fade reverse,
      400ms ease-in-out both slide-right-reverse;
  }

  ::view-transition-new(.nav-back) {
    animation:
      210ms ease-out 150ms both fade,
      400ms ease-in-out both slide-right;
  }

  @keyframes slide-left {
    from {
      transform: translateX(var(--slide-offset));
    }
    to {
      transform: translateX(0);
    }
  }

  @keyframes slide-left-reverse {
    from {
      transform: translateX(0);
    }
    to {
      transform: translateX(calc(-1 * var(--slide-offset)));
    }
  }

  @keyframes slide-right {
    from {
      transform: translateX(calc(-1 * var(--slide-offset)));
    }
    to {
      transform: translateX(0);
    }
  }

  @keyframes slide-right-reverse {
    from {
      transform: translateX(0);
    }
    to {
      transform: translateX(var(--slide-offset));
    }
  }

  .product-info > * {
    animation: content-fade-in 0.3s ease-out forwards;
    opacity: 0;
  }

  .product-info > *:nth-child(1) {
    animation-delay: 0.1s;
  }

  .product-info > *:nth-child(2) {
    animation-delay: 0.15s;
  }

  .product-info > *:nth-child(3) {
    animation-delay: 0.2s;
  }

  @keyframes content-fade-in {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }
}

